import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class MapInverterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Map<String, Integer> m = new HashMap<>();
        m.put("one", 1);
        m.put("two", 2);
        m.put("three", 3);
        try {
            TreeMap<Integer, String> inverted = MapInverter.invertUnique(m);
            check("size of inverted map", 3, inverted == null ? null : inverted.size());
            check("get(1)", "one", inverted == null ? null : inverted.get(1));
            check("get(2)", "two", inverted == null ? null : inverted.get(2));
            check("get(3)", "three", inverted == null ? null : inverted.get(3));
            check("missing key gives null", null, inverted == null ? null : inverted.get(99));
            check("original map unchanged", 3, m.size());

            TreeMap<Integer, String> empty = MapInverter.invertUnique(new HashMap<>());
            check("empty map inverts to empty", 0, empty == null ? null : empty.size());
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

